import{_ as e,o as r,c as a,a6 as o}from"./chunks/framework.B_q3ZJNF.js";const b=JSON.parse('{"title":"回望：Electron、Tauri 与原生绑定的同一原理","description":"","frontmatter":{"title":"回望：Electron、Tauri 与原生绑定的同一原理"},"headers":[],"relativePath":"js-gui-course/13-ecosystem-tradeoffs.md","filePath":"js-gui-course/docs/13-ecosystem-tradeoffs.md"}'),d={name:"js-gui-course/13-ecosystem-tradeoffs.md"};function i(n,t,s,l,c,h){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="回望-electron、tauri-与原生绑定的同一原理" tabindex="-1">回望：Electron、Tauri 与原生绑定的同一原理 <a class="header-anchor" href="#回望-electron、tauri-与原生绑定的同一原理" aria-label="Permalink to &quot;回望：Electron、Tauri 与原生绑定的同一原理&quot;">​</a></h1><p>面试或选型时被问「Electron 为什么装出来 100 多 MB、Tauri 只要几 MB」「为什么 Electron 应用常驻内存动辄几百 MB」「该选哪个」，背营销话术的人给出的答案是「Electron 笨重、Tauri 轻快」。这种回答的问题不在结论对错，而在<strong>说不出为什么</strong>——追问两句就露馅。这门课写到第 12 章，你手里已经有一个自制内核，还在 WebAssembly 和系统 DLL 两个层面真的跨过语言边界，所有流派的方案都能拆成它的零件，差异一目了然。这一章做总装验收：同一原理，三种取舍。</p><h2 id="先把原理钉成一句话" tabindex="-1">先把原理钉成一句话 <a class="header-anchor" href="#先把原理钉成一句话" aria-label="Permalink to &quot;先把原理钉成一句话&quot;">​</a></h2><p>十章浓缩成一张图：<strong>原生世界（窗口资源表 + 消息循环）↔ 序列化边界（binding）↔ JS 世界（注入的全局 API）</strong>，事件从队列回流成回调，能力从桥借出成函数。所有「JS 做桌面端」的方案无一例外是这个结构，它们只在一个问题上分道扬镳：<strong>渲染进程那一侧的「界面引擎」从哪儿来</strong>。</p><h2 id="electron-背一整个浏览器来" tabindex="-1">Electron：背一整个浏览器来 <a class="header-anchor" href="#electron-背一整个浏览器来" aria-label="Permalink to &quot;Electron：背一整个浏览器来&quot;">​</a></h2><p>Electron 的渲染进程 = 完整的 Chromium（Blink 渲染引擎 + V8 + 整套 Web API）+ 一层桥接口。第 7 章说过这个选择的动因：「用 Web 技术写桌面界面」的完整含义是 DOM、CSS、全套浏览器行为，自己造等于重写浏览器，所以干脆链接一个进来。</p><p>用自制内核对照：我们的 <code>renderUI</code> 换成「把 UI 树画成像素」的完整实现（Chromium 干的就是这个），<code>manager</code> 换成真窗口管理，binding 换成 C++ 级绑定，其余结构原样保留。代价与收益都来自这一个决定：收益是界面层生态全盘继承（npm 前端库、CSS、DevTools）、跨平台行为高度一致（每台机器都跑同一版 Chromium，不必管系统差异）；代价是体积（Chromium 本体）与内存（每个渲染进程一套引擎）。另外它继承了第 7 章的多进程模型：崩溃隔离与权限收缴做得很完整，主/渲染/preload 三层职责清晰——<strong>100MB 不是「没优化」，是「把一致性装进了安装包」</strong>。</p><h2 id="tauri-用系统自带的-桥换成-rust" tabindex="-1">Tauri：用系统自带的，桥换成 Rust <a class="header-anchor" href="#tauri-用系统自带的-桥换成-rust" aria-label="Permalink to &quot;Tauri：用系统自带的，桥换成 Rust&quot;">​</a></h2><p>Tauri 的答案：渲染层不背引擎，用操作系统自带的 WebView（Windows 上 WebView2、macOS 上 WKWebView、Linux 上 WebKitGTK）；系统层的 binding 与主进程换成 Rust 程序。对照自制内核：<code>manager</code> 和桥（binding 层）由 Rust 实现，渲染侧还是「某个 Web 引擎 + 注入的 JS API」，只是这个引擎是 OS 的、按需拉起。</p><p>于是取舍反转：安装包只剩你的代码加一层壳（几 MB），内存基线也低。但一致性账单换了债主——<strong>不同系统的 WebView 行为有差异</strong>（老 Windows 还得考虑 WebView2 分发），你的界面实际上跑在「N 个不同版本引擎」上，跨平台调试成本从「打包体积」转移到了「行为差异」。IPC 语义也更严：Tauri 的命令桥 Rust 侧显式声明、参数走 serde 序列化——第 8 章那条「只过纯数据」的规则，在它那里是白纸黑字的编译期约束。</p><h2 id="qt-绑定-原生-ffi-不要-web-界面" tabindex="-1">Qt 绑定 / 原生 FFI：不要 Web 界面 <a class="header-anchor" href="#qt-绑定-原生-ffi-不要-web-界面" aria-label="Permalink to &quot;Qt 绑定 / 原生 FFI：不要 Web 界面&quot;">​</a></h2><p>第三条路（如 Qt 的 JS 绑定、Node 的原生 GUI 绑定）：界面根本不用 Web 技术做。JS 直接绑到原生 GUI 工具包——对照自制内核：我们 <code>renderUI</code> 的 UiNode 树换成 Qt 的控件树，每个控件都是 binding 暴露的句柄（第 5 章的遥控器直接对应 Qt 的对象代理）。这条路的收益是性能与包体（没有浏览器引擎，控件是原生绘制）；代价是<strong>界面生态全靠自己</strong>——没有 CSS、没有现成组件库，binding 面有多大你能用的控件就有多少，且原生绑定层的维护成本（版本升级、内存安全、线程规则）真实存在。它适合控件不多、追求轻量的工具类应用。</p><h2 id="同一张零件表" tabindex="-1">同一张零件表 <a class="header-anchor" href="#同一张零件表" aria-label="Permalink to &quot;同一张零件表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>零件（自制内核）</th><th>Electron</th><th>Tauri</th><th>Qt 绑定</th></tr></thead><tbody><tr><td>界面引擎（renderUI 的真身）</td><td>自带 Chromium</td><td>系统 WebView</td><td>原生控件，无引擎</td></tr><tr><td>binding 层</td><td>C++ 绑定</td><td>Rust 命令桥</td><td>语言绑定/FFI</td></tr><tr><td>进程模型</td><td>完整多进程</td><td>壳进程 + WebView</td><td>通常单进程</td></tr><tr><td>序列化边界</td><td>结构化克隆</td><td>serde 显式声明</td><td>各绑定自定义</td></tr><tr><td>一致性</td><td>每机一致</td><td>依赖系统版本</td><td>依赖工具包版本</td></tr></tbody></table><p>表里没有「谁更好」，只有参数不同：要 Web 生态和绝对一致，付体积；要轻，付行为差异；要极致性能，付生态与维护。选型时先问「界面复杂度和团队技能在哪儿」，再对照这张表付账——这就是原理视角与调包视角的差距。</p><h2 id="这门课的终点自查" tabindex="-1">这门课的终点自查 <a class="header-anchor" href="#这门课的终点自查" aria-label="Permalink to &quot;这门课的终点自查&quot;">​</a></h2><p>合上书之前，用三个问题验收自己（都能在自制内核里指出对应代码）：</p><ol><li>从 <code>win.show()</code> 到窗口出现，经过了哪几站？（句柄 → 桥 invoke → 序列化 → 注册表 → 原生 manager → OS）</li><li><strong>从用户点击到 JS 回调，消息走了哪条路？</strong>（OS 消息 → 队列 → 泵 → 两级路由 → 动作名反查 → 回调）</li><li><strong>为什么函数永远过不了边界、跨进程对象 <code>===</code> 永远 false？</strong>（序列化只复制数据；闭包与引用绑定在各自的内存世界）</li></ol><p>三问答得上来，「调包侠」三个字就可以摘掉了——以后再打开任何一个桌面端框架的文档，你看到的不是一堆 API，而是这张零件表上的已知参数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>Electron 背引擎买一致性，Tauri 借系统引擎买轻量，Qt 绑定绕开 Web 买性能——三种方案是我们十三章内核的三组不同参数，原理结构一条不差。课程终点达成：你拥有一个约六百行、55 条断言背书的 mini-Electron 内核、一次可交互运行（<code>npm run demo</code>）、一次真 FFI 弹窗，以及把它映射到任何真实框架的能力。接下来最好的练习：给自制内核加一个「系统对话框」的 binding，或者把 IPC 通道接进 createApp 让渲染侧也能 invoke 主进程——你会发现，每一次扩展都在重走这门课的某一段。</p>',21)])])}const m=e(d,[["render",i]]);export{b as __pageData,m as default};
